57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /** Dedicated audit trail for owner-lifecycle side effects. */
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
114	        if (normalizedTelephone == null) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
118	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        owner.setTelephone(normalizedTelephone);
123	        if (!owner.isPostcodeValidForCity()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        // Consolidated duplicate detection: all of the former separate telephone, email
127	        // and household checks are now expressed through the single derived identityKey
128	        // (telephone|email|householdId). Reject only when the new owner's WHOLE
129	        // identityKey equals an existing owner's. The household id is assigned later in
130	        // this method, so at this point the new owner's key carries an empty household
131	        // segment; two members of the same household with different telephones therefore
132	        // have different keys and are both allowed.
133	        String identityKey = owner.getIdentityKey();
134	        if (this.clinicService.findAllOwners().stream()
135	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
136	            return new ResponseEntity<>(HttpStatus.CONFLICT);
137	        }
138	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
139	            return new ResponseEntity<>(HttpStatus.CONFLICT);
140	        }
141	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
142	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
143	        }
144	        LocalDate effectiveDate =
145	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
146	        LocalDate registrationDate = toBusinessDay(effectiveDate);
147	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
148	        if (ownersRegisteredToday >= 100) {
149	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
150	        }
151	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
152	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
153	        List<Owner> householdMembers =
154	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
155	        HttpHeaders headers = new HttpHeaders();
156	        owner.setRegistrationDate(registrationDate);
157	        owner.setCustomerCode(customerCode(owner));
158	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
159	        owner.setBulkSignupWarning(bulkSignupWarning);
160	        if (sharesHousehold && !householdMembers.isEmpty()) {
161	            String householdId = householdId(owner.getLastName(), normalizedAddress);
162	            owner.setHouseholdId(householdId);
163	            owner.setHouseholdSize(householdMembers.size() + 1);
164	            for (Owner member : householdMembers) {
165	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
166	                    member.setHouseholdId(householdId);
167	                    this.clinicService.saveOwner(member);
168	                }
169	            }
170	        }
171	        this.clinicService.saveOwner(owner);
172	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
173	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
174	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
175	        headers.setLocation(UriComponentsBuilder.newInstance()
176	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
177	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
183	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
184	        if (currentOwner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
188	        if (normalizedTelephone == null) {
189	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
190	        }
191	        currentOwner.setAddress(ownerFieldsDto.getAddress());
192	        currentOwner.setCity(ownerFieldsDto.getCity());
193	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
194	        currentOwner.setLastName(ownerFieldsDto.getLastName());
195	        currentOwner.setTelephone(normalizedTelephone);
196	        currentOwner.setEmail(ownerFieldsDto.getEmail());
197	        this.clinicService.saveOwner(currentOwner);
198	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Transactional
203	    @Override
204	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner == null) {
207	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	        }
209	        this.clinicService.deleteOwner(owner);
210	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
211	    }
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
216	        Owner owner = this.clinicService.findOwnerById(ownerId);
217	        if (owner == null) {
218	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	        }
220	        HttpHeaders headers = new HttpHeaders();
221	        Pet pet = petMapper.toPet(petFieldsDto);
222	        owner.setId(ownerId);
223	        pet.setOwner(owner);
224	        pet.getType().setName(null);
225	        this.clinicService.savePet(pet);
226	        PetDto petDto = petMapper.toPetDto(pet);
227	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
228	            .buildAndExpand(pet.getId()).toUri());
229	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
235	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
236	        if (currentOwner != null) {
237	            Pet currentPet = this.clinicService.findPetById(petId);
238	            if (currentPet != null) {
239	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
240	                currentPet.setName(petFieldsDto.getName());
241	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
242	                this.clinicService.savePet(currentPet);
243	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
244	            }
245	        }
246	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
247	    }
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
252	        HttpHeaders headers = new HttpHeaders();
253	        Visit visit = visitMapper.toVisit(visitFieldsDto);
254	        Pet pet = new Pet();
255	        pet.setId(petId);
256	        visit.setPet(pet);
257	        this.clinicService.saveVisit(visit);
258	        VisitDto visitDto = visitMapper.toVisitDto(visit);
259	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
260	            .buildAndExpand(visit.getId()).toUri());
261	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
262	    }
263	
264	
265	    /**
266	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
267	     * stripped. When a leading {@code '+'} and country code are present they are kept;
268	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
269	     * is dropped from the national digits. The result must be a {@code '+'} followed
270	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
271	     * is returned to signal a bad request.
272	     */
273	    /**
274	     * Build the customer code for a newly created owner, formatted
275	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
276	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
277	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
278	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
279	     * with its last name. This identity carries no sequence number.
280	     */
281	    private String customerCode(Owner owner) {
282	        String region = owner.getLocality();
283	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
284	        return region + "-" + hash8;
285	    }
286	
287	    /**
288	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
289	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
290	     * treated as empty when {@code null}), already in their normalized forms.
291	     */
292	    private String customerCodeHash(String telephone, String lastName) {
293	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
294	        try {
295	            byte[] digest = MessageDigest.getInstance("SHA-256")
296	                .digest(key.getBytes(StandardCharsets.UTF_8));
297	            StringBuilder sb = new StringBuilder();
298	            for (int i = 0; i < 4; i++) {
299	                sb.append(String.format("%02X", digest[i]));
300	            }
301	            return sb.toString();
302	        }
303	        catch (NoSuchAlgorithmException e) {
304	            throw new IllegalStateException(e);
305	        }
306	    }
307	
308	    /**
309	     * Count the existing owners whose city matches the given one, compared after
310	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
311	     * cap: a city that already holds this many owners is at capacity.
312	     */
313	    private long countOwnersInCity(String city) {
314	        String normalizedCity = normalizeForHousehold(city);
315	        return this.clinicService.findAllOwners().stream()
316	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
317	            .count();
318	    }
319	
320	    /**
321	     * Count the existing owners whose registration date falls on the given day. Used to
322	     * enforce the per-day create limit: once this many owners have been registered today,
323	     * the day is at capacity and further creates are rejected.
324	     */
325	    private long countOwnersRegisteredOn(LocalDate day) {
326	        return this.clinicService.findAllOwners().stream()
327	            .filter(existing -> day.equals(existing.getRegistrationDate()))
328	            .count();
329	    }
330	
331	    /**
332	     * Roll a registration date forward to the next business day: a date falling on a
333	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
334	     * returned unchanged.
335	     */
336	    private LocalDate toBusinessDay(LocalDate date) {
337	        DayOfWeek dayOfWeek = date.getDayOfWeek();
338	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
339	            return date.plusDays(8 - dayOfWeek.getValue());
340	        }
341	        return date;
342	    }
343	
344	    /**
345	     * Find the existing owners that already belong to the same household as the given
346	     * last name and address, i.e. those sharing both fields. Both are compared
347	     * case-insensitively after collapsing runs of whitespace to a single space and
348	     * trimming the ends.
349	     */
350	    private List<Owner> findHouseholdMembers(String lastName, String address) {
351	        String normalizedLastName = normalizeForHousehold(lastName);
352	        String normalizedAddress = normalizeForHousehold(address);
353	        return this.clinicService.findAllOwners().stream()
354	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
355	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
356	            .toList();
357	    }
358	
359	    /**
360	     * Count the existing owners that already share both the given first and last
361	     * name, compared case-insensitively. Used to populate an owner's namesake count
362	     * at creation time, reflecting how many owners with the same name existed before
363	     * this one was created.
364	     */
365	    private int countNamesakes(String firstName, String lastName) {
366	        String normalizedFirstName = normalizeName(firstName);
367	        String normalizedLastName = normalizeName(lastName);
368	        return (int) this.clinicService.findAllOwners().stream()
369	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
370	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
371	            .count();
372	    }
373	
374	    private String normalizeName(String value) {
375	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
376	    }
377	
378	    /**
379	     * Build a stable identifier shared by all owners of one household. It is derived
380	     * deterministically from the normalized last name and address, so every owner at
381	     * the same household resolves to the same value regardless of creation order.
382	     */
383	    private String householdId(String lastName, String address) {
384	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
385	        try {
386	            byte[] digest = MessageDigest.getInstance("SHA-256")
387	                .digest(key.getBytes(StandardCharsets.UTF_8));
388	            StringBuilder sb = new StringBuilder();
389	            for (int i = 0; i < 6; i++) {
390	                sb.append(String.format("%02X", digest[i]));
391	            }
392	            return "HH-" + sb;
393	        }
394	        catch (NoSuchAlgorithmException e) {
395	            throw new IllegalStateException(e);
396	        }
397	    }
398	
399	    private String normalizeForHousehold(String value) {
400	        if (value == null) {
401	            return "";
402	        }
403	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
404	    }
405	
406	    private String normalizeTelephone(String telephone) {
407	        if (telephone == null) {
408	            return null;
409	        }
410	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
411	        String digits;
412	        if (cleaned.startsWith("+")) {
413	            digits = cleaned.substring(1);
414	        } else {
415	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
416	            digits = "61" + national;
417	        }
418	        if (!digits.matches("[0-9]{8,15}")) {
419	            return null;
420	        }
421	        if (!hasValidNationalLength(digits)) {
422	            return null;
423	        }
424	        return "+" + digits;
425	    }
426	
427	    /**
428	     * Validate the national-number length of an E.164 number (the digits, without the
429	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
430	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
431	     * codes without a known rule are accepted as-is.
432	     */
433	    private boolean hasValidNationalLength(String digits) {
434	        if (digits.startsWith("61")) {
435	            return digits.length() - 2 == 9;
436	        }
437	        if (digits.startsWith("1")) {
438	            return digits.length() - 1 == 10;
439	        }
