29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "postcode")
64	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
65	    private String postcode;
66	
67	    @Column(name = "customer_code")
68	    private String customerCode;
69	
70	    @Column(name = "household_id")
71	    private String householdId;
72	
73	    @Column(name = "namesake_count")
74	    private Integer namesakeCount;
75	
76	    @Column(name = "bulk_signup_warning")
77	    private Boolean bulkSignupWarning;
78	
79	    @Column(name = "household_size")
80	    private Integer householdSize;
81	
82	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
83	    private Set<Pet> pets;
84	
85	    /** Common street-type abbreviations expanded during address normalization. */
86	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
87	        "ST", "STREET",
88	        "RD", "ROAD",
89	        "AVE", "AVENUE");
90	
91	    /** Fixed city-to-region table used to derive an owner's locality. */
92	    private static final Map<String, String> CITY_REGION = Map.of(
93	        "Sydney", "NSW",
94	        "Melbourne", "VIC",
95	        "Brisbane", "QLD");
96	
97	    /** Fixed region-to-postcode-range table (inclusive) used to validate a postcode. */
98	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
99	        "NSW", new int[] {2000, 2099},
100	        "VIC", new int[] {3000, 3099},
101	        "QLD", new int[] {4000, 4099});
102	
103	    public String getAddress() {
104	        return this.address;
105	    }
106	
107	    /**
108	     * Set the owner's address, normalizing it to a canonical form so it is both
109	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
110	     * internal runs of whitespace are collapsed to a single space, the value is
111	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
112	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
113	     * left as-is.
114	     */
115	    public void setAddress(String address) {
116	        this.address = normalizeAddress(address);
117	    }
118	
119	    /**
120	     * Normalize an address string to its canonical form: trimmed, whitespace
121	     * collapsed, upper-cased, with common street-type abbreviations expanded.
122	     * Returns {@code null} for a {@code null} input; a value that is blank once
123	     * trimmed normalizes to the empty string.
124	     */
125	    public static String normalizeAddress(String address) {
126	        if (address == null) {
127	            return null;
128	        }
129	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
130	        if (collapsed.isEmpty()) {
131	            return "";
132	        }
133	        String[] tokens = collapsed.split(" ");
134	        StringBuilder sb = new StringBuilder();
135	        for (int i = 0; i < tokens.length; i++) {
136	            if (i > 0) {
137	                sb.append(' ');
138	            }
139	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
140	        }
141	        return sb.toString();
142	    }
143	
144	    public String getCity() {
145	        return this.city;
146	    }
147	
148	    public void setCity(String city) {
149	        this.city = city;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    public String getEmail() {
161	        return this.email;
162	    }
163	
164	    /**
165	     * Set the owner's email address, normalizing it to lower case so it is both
166	     * stored and returned in a canonical form. A {@code null} value is left as-is.
167	     */
